pragma solidity >=0.8.0;
contract HashPackedStaticLiteral {
    address constant A = 0x000000000000000000000000000000000000dEaD;
    bytes public packedTuple;
    bytes public encodedTuple;
    bytes public packedBytes4;
    bytes public packedUint16;
    bytes32 public pKeccak;
    bytes32 public pSha;
    bytes20 public pRipemd;
    bytes32 public eKeccak;

    function set() external {
        packedTuple = abi.encodePacked(A, true, bytes4(0xdeadbeef));
        encodedTuple = abi.encode(A, true, bytes4(0xdeadbeef));
        packedBytes4 = abi.encodePacked(bytes4(0xdeadbeef));
        packedUint16 = abi.encodePacked(uint16(0x1234));
        pKeccak = keccak256(abi.encodePacked(A, true, bytes4(0xdeadbeef)));
        pSha = sha256(abi.encodePacked(A, true, bytes4(0xdeadbeef)));
        pRipemd = ripemd160(abi.encodePacked(A, true, bytes4(0xdeadbeef)));
        eKeccak = keccak256(abi.encode(A, true, bytes4(0xdeadbeef)));
    }
}
